// Converts the captured risk-gate report into a script the scenes can load.
// The Markdown in assets/data/ is real output of the risk-gate v0.1.0 binary
// (see docs/demo/README.md for how it was produced); scenes must not edit it.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const report = readFileSync(join(root, "assets/data/report-failed.md"), "utf8").replace(/\n+$/, "");
const body =
  "/* Generated by scripts/report-data.mjs from assets/data/report-failed.md. */\n" +
  `window.RG_REPORT = ${JSON.stringify({ failed: report }, null, 2)};\n`;
writeFileSync(join(root, "assets/data/report.js"), body);
console.log("wrote assets/data/report.js");
